// Pure lockfile-evidence logic — no network, no DOM, no filesystem. Ports the
// same classification rules as npm_deployment_evidence.py (the CLI this venture
// shipped with first) so the browser tool and the CLI agree on every verdict.
// Loadable as a plain <script> in the browser (defines globals, no bundler) and
// requireable under `node --test`.

const LIMITATIONS = [
  "This report reads package-lock.json v2/v3 only; it does not inspect yarn or pnpm projects.",
  "A package is marked build-only when every installed location is reached through a known build dependency.",
  "This is static lockfile evidence, not proof: it cannot see dynamic imports or runtime loading.",
  "Build-only means absent from the deployed application artifact, not safe on the machine that runs the build.",
  "This is evidence, not a vulnerability determination, attestation, or compliance advice.",
];

function packageName(path) {
  const marker = "node_modules/";
  const idx = path.lastIndexOf(marker);
  if (idx === -1) return null;
  const name = path.slice(idx + marker.length);
  return name || null;
}

/**
 * Yarn and pnpm lockfiles are not JSON. Without this check, dropping one
 * surfaces as "not valid JSON" — true, but it strands a visitor who brought
 * the only lockfile their project has. Name the format and the supported one
 * instead. `fileName` is optional; content detection covers paste.
 */
function unsupportedLockfileError(text, fileName) {
  const name = String(fileName || "")
    .trim()
    .split(/[\\/]/)
    .pop()
    .toLowerCase();
  const head = String(text || "").slice(0, 400);
  const looksYarn =
    name === "yarn.lock" ||
    /^#\s*yarn\b/i.test(head) ||
    /\byarn lockfile v\d/i.test(head);
  const looksPnpm =
    name === "pnpm-lock.yaml" ||
    name === "pnpm-lock.yml" ||
    (/^lockfileVersion:\s*\d/m.test(head) && /\bimporters:\s*$/m.test(head));
  if (looksYarn) {
    return (
      "This file is a yarn.lock. This tool only reads package-lock.json v2 or v3 " +
        "(npm 7+). Generate one with `npm install`, or keep using yarn's own audit tools."
    );
  }
  if (looksPnpm) {
    return (
      "This file is a pnpm-lock.yaml. This tool only reads package-lock.json v2 or v3 " +
        "(npm 7+). Generate one with `npm install`, or keep using pnpm's own audit tools."
    );
  }
  return null;
}

/**
 * Parses package-lock.json text into { root, packages }. `root` is the parsed
 * lockfile object; `packages` maps a package name to every install location
 * that resolved it. Throws with a message meant to be shown to the visitor
 * directly — this is the only place lockfile shape is validated.
 */
function parseLockfile(text, fileName) {
  const unsupported = unsupportedLockfileError(text, fileName);
  if (unsupported) {
    throw new Error(unsupported);
  }
  let raw;
  try {
    raw = JSON.parse(text);
  } catch {
    throw new Error("That file is not valid JSON. Paste or drop the package-lock.json itself, not a different file.");
  }
  if (raw === null || typeof raw !== "object") {
    throw new Error("That file is not valid JSON. Paste or drop the package-lock.json itself, not a different file.");
  }
  const version = raw.lockfileVersion;
  if ((version !== 2 && version !== 3) || typeof raw.packages !== "object" || raw.packages === null || Array.isArray(raw.packages)) {
    throw new Error(
      "This needs package-lock.json v2 or v3 with a \"packages\" map (npm 7+). " +
        "Delete the lockfile and run `npm install` again to upgrade an older one, " +
        "or check package.json — yarn.lock and pnpm-lock.yaml are not supported.",
    );
  }
  // Package names are data, including names inherited by ordinary objects.
  const packages = Object.create(null);
  for (const [location, entry] of Object.entries(raw.packages)) {
    if (entry === null || typeof entry !== "object" || Array.isArray(entry) || !entry.version) continue;
    const name = packageName(location);
    if (!name) continue;
    if (!packages[name]) packages[name] = [];
    packages[name].push({ path: location, ...entry });
  }
  return { root: raw, packages };
}

function declaredDependencies(rootEntry) {
  const deps = rootEntry && typeof rootEntry === "object" ? rootEntry.dependencies : null;
  return new Set(deps && typeof deps === "object" ? Object.keys(deps) : []);
}

function classify(name, locations, declared) {
  if (declared.has(name)) {
    return { buildOnly: false, reason: "declared by the application; direct production use is possible" };
  }
  if (locations.some((location) => !location.dev)) {
    return { buildOnly: false, reason: "at least one install location is on a production path" };
  }
  return { buildOnly: true, reason: "every install location is marked dev-only by npm" };
}

/** Builds the full evidence report from raw lockfile text and a display file name. */
function buildReport(text, fileName) {
  const { root, packages } = parseLockfile(text, fileName);
  const declared = declaredDependencies(root.packages[""]);
  const rows = Object.keys(packages)
    .sort()
    .map((name) => {
      const locations = packages[name];
      const { buildOnly, reason } = classify(name, locations, declared);
      return {
        name,
        versions: [...new Set(locations.map((item) => item.version))].sort(),
        locations: locations.map((item) => item.path),
        surface: buildOnly ? "build-only" : "production",
        reason,
      };
    });
  const counts = { production: 0, "build-only": 0 };
  for (const row of rows) counts[row.surface] += 1;
  return {
    generatedOn: new Date().toISOString().slice(0, 10),
    lockfile: fileName || "package-lock.json",
    componentCount: rows.length,
    counts,
    components: rows,
    limitations: LIMITATIONS,
  };
}

function toMarkdown(report) {
  const lines = [
    "# npm deployment evidence",
    "",
    `Checked \`${report.lockfile}\` on ${report.generatedOn}: **${report.componentCount} components**.`,
    "",
    "This report shows package-lockfile evidence about dependency reachability. It does not claim that a project is secure or compliant.",
    "",
    "## Summary",
    "",
    `- Production-path components: **${report.counts.production || 0}**`,
    `- Build-only components: **${report.counts["build-only"] || 0}**`,
    "",
    "## Components",
    "",
    "| Package | Version(s) | Surface | Evidence |",
    "|---|---|---|---|",
  ];
  for (const row of report.components) {
    lines.push(`| \`${row.name}\` | ${row.versions.join(", ")} | ${row.surface} | ${row.reason} |`);
  }
  lines.push("", "## Limitations", "");
  for (const limitation of report.limitations) lines.push(`- ${limitation}`);
  lines.push(
    "",
    "**No warranty.** This tool is provided free and as-is, without warranty of any kind, express or implied. It is not legal, tax, financial, medical, or engineering advice, and it does not replace a qualified professional. **You are responsible for reviewing and verifying its output before relying on it**, and for meeting any obligation it helps prepare for. To the maximum extent permitted by law, the authors accept no liability for any loss or damage arising from its use.",
  );
  return lines.join("\n") + "\n";
}

function toJson(report) {
  return JSON.stringify(report, null, 2) + "\n";
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    parseLockfile,
    buildReport,
    toMarkdown,
    toJson,
    packageName,
    unsupportedLockfileError,
    LIMITATIONS,
  };
}

style.css.text:
:root {
  color-scheme: light dark;
  --bg: #ffffff;
  --fg: #1a1a1a;
  --muted: #5f6368;
  --border: #e2e2e2;
  --accent: #2563eb;
  --good: #16a34a;
  --warn: #d97706;
  --card-bg: #f8f9fa;
  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --mono: ui-monospace, SFMono-Regular, Menlo, monospace;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #14161a;
    --fg: #f1f2f4;
    --muted: #9aa0a6;
    --border: #2c2f34;
    --card-bg: #1c1f24;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: var(--font);
  line-height: 1.5;
}

.page {
  max-width: 760px;
  margin: 0 auto;
  padding: 2.5rem 1.25rem 4rem;
}

.hero {
  text-align: center;
  margin-bottom: 2rem;
}

.hero h1 {
  font-size: 2rem;
  margin: 0 0 0.5rem;
}

.tagline {
  color: var(--muted);
  font-size: 1.05rem;
  margin: 0 auto;
  max-width: 56ch;
}

.tagline code {
  font-family: var(--mono);
  font-size: 0.9em;
}

.drop-zone {
  border: 2px dashed var(--border);
  border-radius: 12px;
  padding: 1.75rem 1.25rem;
  text-align: center;
  background: var(--card-bg);
}

.drop-zone.dragover {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 8%, var(--card-bg));
}

.drop-zone p {
  margin: 0.4rem 0;
  color: var(--muted);
}

.file-label {
  display: inline-block;
  padding: 0.6rem 1.1rem;
  font-weight: 600;
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
}

.file-label input[type="file"] {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
}

.or-line {
  font-size: 0.9rem;
}

#lockfile-paste {
  width: 100%;
  font-family: var(--mono);
  font-size: 0.85rem;
  padding: 0.6rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  color: var(--fg);
  resize: vertical;
}

#parse-pasted {
  margin-top: 0.6rem;
  padding: 0.6rem 1.1rem;
  font-size: 0.95rem;
  font-weight: 600;
  color: #fff;
  background: var(--accent);
  border: none;
  border-radius: 8px;
  cursor: pointer;
}

#parse-pasted:hover,
.file-label:hover {
  filter: brightness(1.08);
}

.example-line {
  text-align: center;
  font-size: 0.95rem;
  opacity: 0.85;
  max-width: 50rem;
  margin: 0.9rem auto 0;
}

.link-button {
  background: none;
  border: 0;
  padding: 0;
  font: inherit;
  color: inherit;
  text-decoration: underline;
  cursor: pointer;
}

.link-button:hover {
  filter: brightness(1.3);
}

.link-button:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 2px;
}

.error {
  text-align: center;
  color: #dc2626;
  font-weight: 600;
}

.summary-card {
  display: flex;
  justify-content: center;
  gap: 2rem;
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.25rem;
  margin: 1.5rem 0 1rem;
  background: var(--card-bg);
}

.summary-stat {
  text-align: center;
}

.summary-number {
  display: block;
  font-size: 2rem;
  font-weight: 800;
}

.summary-number.production { color: var(--good); }
.summary-number.build-only { color: var(--warn); }

.summary-label {
  font-size: 0.8rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.report-actions {
  display: flex;
  justify-content: center;
  gap: 0.75rem;
  margin-bottom: 1.25rem;
}

.report-actions button {
  padding: 0.55rem 1rem;
  font-size: 0.9rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  color: var(--fg);
  cursor: pointer;
}

.report-actions button:hover {
  border-color: var(--accent);
}

.table-wrap {
  overflow-x: auto;
}

.component-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
}

.component-table th,
.component-table td {
  text-align: left;
  padding: 0.55rem 0.6rem;
  border-bottom: 1px solid var(--border);
  vertical-align: top;
}

.component-table code {
  font-family: var(--mono);
  font-size: 0.85em;
}

.component-table .reason {
  color: var(--muted);
}

.badge {
  display: inline-block;
  padding: 0.15rem 0.5rem;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 600;
}

.badge.production {
  background: color-mix(in srgb, var(--good) 18%, transparent);
  color: var(--good);
}

.badge.build-only {
  background: color-mix(in srgb, var(--warn) 18%, transparent);
  color: var(--warn);
}

.disclaimer {
  margin-top: 3rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border);
  font-size: 0.9rem;
  color: var(--muted);
}

.disclaimer h2 {
  font-size: 1rem;
  color: var(--fg);
}

.disclaimer code {
  font-family: var(--mono);
  font-size: 0.9em;
}

.footer {
  margin-top: 2rem;
  text-align: left;
  font-size: 0.85rem;
  color: var(--muted);
}

.footer p {
  margin: 0.75rem 0;
}

.privacy {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0.75rem 0;
}

usage.js.text:
// Local-first, aggregate-only usage counting, per portfolio/usage/usage.yaml:
// count events, never people. No lockfile contents, no package names, no file
// names — just an event name and a day, kept in this browser's own
// localStorage. Nothing is sent anywhere; there is no server for it to go to.
// Off-switchable, and honors Do Not Track / Global Privacy Control.

const STORAGE_KEY = "npm-deployment-evidence:usage";
const OPT_OUT_KEY = "npm-deployment-evidence:usage:off";

function hasStorage() {
  try { return typeof localStorage !== "undefined"; } catch { return false; }
}

function browserOptedOut() {
  try {
    return navigator?.doNotTrack === "1" || navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

function isUsageEnabled() {
  if (!hasStorage() || browserOptedOut()) return false;
  try { return localStorage.getItem(OPT_OUT_KEY) !== "1"; } catch { return false; }
}

function setUsageEnabled(enabled) {
  if (!hasStorage()) return;
  try {
    if (enabled) localStorage.removeItem(OPT_OUT_KEY);
    else localStorage.setItem(OPT_OUT_KEY, "1");
  } catch { /* usage must never affect the report */ }
}

function recordUsage(eventName) {
  if (!isUsageEnabled() || !eventName) return;
  try {
    const day = new Date().toISOString().slice(0, 10);
    const events = JSON.parse(localStorage.getItem(STORAGE_KEY) || "{}");
    const key = `${eventName}:${day}`;
    events[key] = (events[key] || 0) + 1;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(events));
  } catch { /* private browsing and full storage are expected */ }
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { isUsageEnabled, setUsageEnabled, recordUsage, STORAGE_KEY, OPT_OUT_KEY };
}
